import type { Vec3 } from '../../contracts/math';
import type { Hole, ObstacleDescriptor, SurfaceDescriptor, SurfaceMaterial } from '../types';

/**
 * Shared layout primitives for course-data modules. Courses stay plain data;
 * these helpers only cut down on repetition while keeping every hole explicit.
 */

export const v = (x: number, y: number, z: number): Vec3 => ({ x, y, z });

/** Floors are thin slabs, so the walkable top sits at y + THICKNESS / 2. */
export const THICKNESS = 0.3;

/** Tilt around the X axis. A negative angle lifts the far (+Z) end of a slab. */
export const tiltX = (angle: number) => ({
  x: Math.sin(angle / 2),
  y: 0,
  z: 0,
  w: Math.cos(angle / 2),
});

/** Axis-aligned floor slab centred on (x, y, z). */
export const pad = (
  id: string,
  x: number,
  z: number,
  sx: number,
  sz: number,
  material: SurfaceMaterial,
  y = 0,
  friction?: number,
): SurfaceDescriptor => ({
  id,
  transform: { position: v(x, y, z) },
  shape: 'box',
  size: v(sx, THICKNESS, sz),
  material,
  ...(friction === undefined ? {} : { friction }),
});

/** Ramp connecting elevation `from` to elevation `to` over `run` metres along +Z. */
export const slope = (
  id: string,
  x: number,
  z: number,
  sx: number,
  run: number,
  from: number,
  to: number,
  material: SurfaceMaterial,
): SurfaceDescriptor => ({
  id,
  transform: { position: v(x, (from + to) / 2, z), rotation: tiltX(-Math.atan2(to - from, run)) },
  shape: 'ramp',
  size: v(sx, THICKNESS, Math.hypot(run, to - from)),
  material,
});

export const wall = (
  id: string,
  x: number,
  z: number,
  sx: number,
  sz: number,
  y = 0.7,
  h = 1.4,
): ObstacleDescriptor => ({ id, type: 'wall', transform: { position: v(x, y, z) }, size: v(sx, h, sz) });

export const block = (
  id: string,
  x: number,
  z: number,
  sx: number,
  sz: number,
  y = 0.6,
  h = 1.2,
): ObstacleDescriptor => ({ id, type: 'block', transform: { position: v(x, y, z) }, size: v(sx, h, sz) });

export const pillar = (
  id: string,
  x: number,
  z: number,
  diameter: number,
  h = 1.6,
  y = 0.8,
): ObstacleDescriptor => ({
  id,
  type: 'pillar',
  transform: { position: v(x, y, z) },
  size: v(diameter, h, diameter),
});

export const bumper = (
  id: string,
  x: number,
  z: number,
  diameter = 1,
  restitution = 1.25,
  y = 0.5,
): ObstacleDescriptor => ({
  id,
  type: 'bumper',
  transform: { position: v(x, y, z) },
  size: v(diameter, 1, diameter),
  restitution,
});

/** Sliding barrier that sweeps along X. */
export const gate = (
  id: string,
  x: number,
  z: number,
  sx: number,
  speed: number,
  distance: number,
  phase = 0,
  y = 0.85,
  h = 1.5,
): ObstacleDescriptor => ({
  id,
  type: 'gate',
  transform: { position: v(x, y, z) },
  size: v(sx, h, 0.35),
  motion: { kind: 'translate', axis: v(1, 0, 0), speed, distance, phase },
});

export const spinner = (
  id: string,
  x: number,
  z: number,
  length: number,
  speed: number,
  y = 0.75,
): ObstacleDescriptor => ({
  id,
  type: 'spinner',
  transform: { position: v(x, y, z) },
  size: v(length, 0.3, 0.45),
  motion: { kind: 'rotate', axis: v(0, 1, 0), speed },
});

/** Moving platform that ferries the ball sideways across a gap. */
export const shuttle = (
  id: string,
  x: number,
  z: number,
  sx: number,
  sz: number,
  speed: number,
  distance: number,
  y = 0.15,
): ObstacleDescriptor => ({
  id,
  type: 'platform',
  transform: { position: v(x, y, z) },
  size: v(sx, 0.35, sz),
  motion: { kind: 'translate', axis: v(1, 0, 0), speed, distance },
});

export const gap = (
  id: string,
  x: number,
  z: number,
  sx: number,
  sz: number,
  penaltyStrokes = 1,
  y = -0.9,
): ObstacleDescriptor => ({
  id,
  type: 'void',
  transform: { position: v(x, y, z) },
  size: v(sx, 1, sz),
  penaltyStrokes,
});

export const resetZone = (
  id: string,
  x: number,
  z: number,
  sx: number,
  sz: number,
  penaltyStrokes = 2,
  y = -1.2,
): ObstacleDescriptor => ({
  id,
  type: 'reset-zone',
  transform: { position: v(x, y, z) },
  size: v(sx, 1, sz),
  penaltyStrokes,
});

export const water = (
  id: string,
  x: number,
  z: number,
  sx: number,
  sz: number,
  penaltyStrokes = 1,
  y = 0.1,
): ObstacleDescriptor => ({
  id,
  type: 'water',
  transform: { position: v(x, y, z) },
  size: v(sx, 0.4, sz),
  penaltyStrokes,
});

/** Cup resting on a floor whose slab centre is at `elevation`. */
export const cupAt = (x: number, z: number, elevation = 0): Hole['cup'] => ({
  position: v(x, elevation + 0.12, z),
  radius: 0.32,
  captureDepth: 0.28,
});

/** Ball spawn just above a floor whose slab centre is at `elevation`. */
export const startAt = (x: number, z: number, elevation = 0): Vec3 => v(x, elevation + 0.35, z);

/** Bounds that wrap every surface of a hole with a margin for camera work. */
export const fitBounds = (
  surfaces: readonly SurfaceDescriptor[],
  margin = 3,
  headroom = 8,
): Hole['bounds'] => {
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;
  let minZ = Infinity;
  let maxZ = -Infinity;
  for (const surface of surfaces) {
    const p = surface.transform.position;
    minX = Math.min(minX, p.x - surface.size.x / 2);
    maxX = Math.max(maxX, p.x + surface.size.x / 2);
    minY = Math.min(minY, p.y);
    maxY = Math.max(maxY, p.y);
    minZ = Math.min(minZ, p.z - surface.size.z / 2);
    maxZ = Math.max(maxZ, p.z + surface.size.z / 2);
  }
  if (!Number.isFinite(minX)) {
    throw new Error('fitBounds requires at least one surface');
  }
  return {
    min: v(minX - margin, minY - 4, minZ - margin),
    max: v(maxX + margin, maxY + headroom, maxZ + margin),
  };
};

export const makeHole = (
  id: string,
  name: string,
  par: number,
  spawn: Vec3,
  cup: Hole['cup'],
  surfaces: SurfaceDescriptor[],
  obstacles: ObstacleDescriptor[],
): Hole => ({ id, name, par, spawn, cup, bounds: fitBounds(surfaces), surfaces, obstacles });
